import json
from dataclasses import dataclass


@dataclass(frozen=True)
class User:
    name: str
    active: bool = True


def decode_user(payload: str) -> User:
    raw = json.loads(payload)
    # v1 omitted active; v2 makes it explicit while preserving old payloads.
    return User(name=str(raw["name"]), active=bool(raw.get("active", True)))


def encode_user(user: User) -> str:
    return json.dumps({"name": user.name, "active": user.active}, sort_keys=True)
